D.forEach(t=>{t.k=COLORES[t.n]||t.k});
/* tcol(equipo o id, lado 0/1) -> color hex del equipo; si no tiene, azul (local) o rojo (visitante) */
function tcol(t,i){let n=null,k=null;try{if(typeof t=='object'&&t){n=t.n;k=t.k}else if(t!=null&&typeof G!='undefined'&&G.T&&G.T[t]){n=G.T[t].n;k=G.T[t].k}}catch(e){}
 return COLORES[n]||k||(i==1?'#ff4d43':'#2f7bff')}
/* tcSet(elemento, [idLocal, idVisitante]) -> pone --c0 (local) y --c1 (visitante) en el elemento y en <html> para que los use el CSS */
function tcSet(el,ids){const a=tcol(ids[0],0),b=tcol(ids[1],1);[el,document.documentElement].forEach(e=>{if(e){e.style.setProperty('--c0',a);e.style.setProperty('--c1',b)}})}
